     1→# ABOUTME: Semantic action for Assignment - binds variables to IR nodes using SSA
     2→# ABOUTME: Assignment handles simple assignment (=) with direct data flow
     3→
     4→use 5.42.0;
     5→use experimental 'class';
     6→use builtin qw(blessed);
     7→
     8→# IR Quality Heuristic: Pick best parse based on IR completeness
     9→# Prefer parses with more defined structure (more nodes in subtree)
    10→sub _pick_best_ir_value($candidates, $builder) {
    11→    return $candidates->[0] if $candidates->@* == 1;
    12→
    13→    # Count IR nodes in the value subtree for each candidate
    14→    # Build scored array manually to avoid map block with hash constructor
    15→    my @scored = ();
    16→    for my $cand ($candidates->@*) {
    17→        my $score = _count_ir_nodes($cand, $builder->graph);
    18→        my $entry = { value => $cand, score => $score };
    19→        push(@scored, $entry);
    20→    }
    21→
    22→    # Sort by score descending (more nodes = more complete = better)
    23→    # Using manual sort to avoid sort block syntax
    24→    my $best = $scored[0];
    25→    for my $candidate (@scored) {
    26→        if ($candidate->{score} > $best->{score}) {
    27→            $best = $candidate;
    28→        }
    29→    }
    30→
    31→    return $best->{value};
    32→}
    33→
    34→# Recursively count nodes in IR subtree
    35→# More nodes indicates more complete parse
    36→sub _count_ir_nodes($node, $graph) {
    37→    return 0 unless $node;
    38→    return 0 unless blessed($node) && $node->can('op');
    39→
    40→    my $count = 1;  # Count self
    41→
    42→    # Recursively count children based on operation type
    43→    my $op = $node->op;
    44→
    45→    # Binary operations have left/right children
    46→    if ($op eq 'Add' || $op eq 'Subtract' || $op eq 'Multiply' || $op eq 'Divide' ||
    47→        $op eq 'GT' || $op eq 'LT' || $op eq 'EQ' || $op eq 'NE' || $op eq 'LE' || $op eq 'GE') {
    48→
    49→        my $left = $node->attributes->{left};
    50→        if ($left) {
    51→            if ($left->{op} eq 'NodeRef') {
    52→                my $left_node = $graph->get_node($left->{node_id});
    53→                $count += _count_ir_nodes($left_node, $graph);
    54→            }
    55→        }
    56→
    57→        my $right = $node->attributes->{right};
    58→        if ($right) {
    59→            if ($right->{op} eq 'NodeRef') {
    60→                my $right_node = $graph->get_node($right->{node_id});
    61→                $count += _count_ir_nodes($right_node, $graph);
    62→            }
    63→        }
    64→    }
    65→
    66→    # Note: Store nodes removed in SSA refactor - variables are direct data flow
    67→
    68→    return $count;
    69→}
    70→
    71→class Chalk::Grammar::Chalk::Rule::Assignment :isa(Chalk::GrammarRule) {
    72→    method evaluate($context) {
    73→        # Assignment -> Ternary (pass-through)
    74→        # Assignment -> Ternary WS_OPT '=' WS_OPT Assignment
    75→        # Assignment -> Ternary WS_OPT %ASSIGN_OP% WS_OPT Assignment (TODO: compound assignment)
    76→
    77→        my @children = $context->children->@*;
    78→        my $builder = $context->env->{ir_builder};
    79→
    80→        # Check if this is an assignment operation (has '=' operator)
    81→        my $has_assignment = 0;
    82→        my $equals_index = -1;
    83→        for my $i (0..$#children) {
    84→            my $child = $children[$i]->extract;
    85→            if (defined($child) && !ref($child) && $child eq '=') {
    86→                $has_assignment = 1;
    87→                $equals_index = $i;
    88→                last;
    89→            }
    90→        }
    91→
    92→        # If no '=' operator, just pass through the Ternary child
    93→        return $context->child(0) unless $has_assignment;
    94→
    95→        # We have an assignment: Ternary = Assignment
    96→        return $context->child(0) unless $builder;
    97→
    98→        # Get left side (variable being assigned to)
    99→        my $lhs = $context->child(0);
   100→
   101→        # Extract variable name from lhs
   102→        # Two possible cases:
   103→        # 1. Variable metadata hash (from ScalarVar before Primary processes it)
   104→        # 2. Proj node (function parameters)
   105→        # Note: With SSA-style variables, we no longer create Load nodes
   106→        my $var_name;
   107→        if (ref($lhs) eq 'HASH' && $lhs->{type} eq 'scalar_var') {
   108→            # Case 1: Variable metadata
   109→            $var_name = $lhs->{name};
   110→        } elsif (blessed($lhs) && $lhs->can('op') && $lhs->op eq 'Proj') {
   111→            # Case 2: Proj node from parameter
   112→            $var_name = $lhs->label;  # Use label field, not attributes
   113→        } else {
   114→            # Can't handle this lhs type for assignment
   115→            return $context->child(0);
   116→        }
   117→
   118→        # Get right side (value to assign) - after '=' + WS_OPT, which is equals_index + 2
   119→        my $rhs_index = $equals_index + 2;
   120→
   121→        # Query parse alternatives for RHS to handle ambiguous parses
   122→        # For expressions like "$i = $i - 1", SPPF may create multiple parse trees
   123→        my @rhs_alternatives = $context->child_alternatives($rhs_index);
   124→
   125→        my $rhs;
   126→        if (@rhs_alternatives > 1) {
   127→            # Multiple parse alternatives exist - evaluate each and pick best
   128→            # The "best" is the one with most complete IR structure
   129→
   130→            my $candidate_values = [];
   131→            for my $alt_ctx (@rhs_alternatives) {
   132→                # Extract semantic value from this alternative's context
   133→                my $alt_value = $alt_ctx->extract if $alt_ctx->can('extract');
   134→                next unless (blessed($alt_value) && $alt_value->can('id'));
   135→                push($candidate_values->@*, $alt_value);
   136→            }
   137→
   138→            # If we got candidates, pick the best based on IR quality
   139→            my $num_candidates = scalar($candidate_values->@*);
   140→            if ($num_candidates > 0) {
   141→                $rhs = _pick_best_ir_value($candidate_values, $builder);
   142→            } else {
   143→                # Fallback to default if no valid candidates
   144→                $rhs = $context->child($rhs_index);
   145→            }
   146→        } else {
   147→            # No ambiguity - use the single parse (default behavior)
   148→            $rhs = $context->child($rhs_index);
   149→        }
